  "knowledge": "Annualized Side Effect Score",
  "description": "A projected total side effect burden over a 12-month period, assuming a standard number of medications.",
  "definition": "\text{Score} = \text{Numeric value of medication side effect density} \times \text{number of medications} \times 12"
}

{
  "id": 10,
  "knowledge": "High-Risk Patient",
  "description": "Identifies patients with elevated suicide risk or severe symptoms.",
  "definition": "A patient whose assessed suicide risk is 'High', or whose depression score (PHQ-9) is over 15, or whose anxiety score (GAD-7) is over 15."
}

{
  "id": 26,
  "knowledge": "Treatment Adherence",
  "description": "Illustrates the value of treatment adherence levels.",
  "definition": "Ranges from Non-compliant to High/Compliant. Non-compliant indicates no adherence, Low indicates occasional adherence, Medium indicates regular adherence, and High/Compliant indicates consistent adherence."
}

{
  "id": 69,
  "knowledge": "Annual Treatment Burden",
  "description": "The projected total number of side effects over a 12-month period, assuming a standard number of medications.",
  "definition": "\text{Burden} = \text{Numeric value of medication side effect density} \times \text{number of medications} \times 12"
}

{
  "id": 85,
  "knowledge": "High-Burden Prevalence Rate",
  "description": "Calculates the percentage of patients within a specific cohort that are flagged as having an Annualized Side Effect Score over the defined threshold.",
  "definition": "The percentage of patients within a cohort who have an 'Annualized Side Effect Score' greater than a defined threshold."
}
